def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [[0] * w for _ in range(h)]

    colors = {v for _, _, v in points}
    if len(colors) == 1:
        v = next(iter(colors))
        return [[v] * w for _ in range(h)]

    coords = [
        lambda r, c: r + c,
        lambda r, c: r - c,
        lambda r, c: r,
        lambda r, c: c,
    ]
    # Choose the direction in which the colored cells form the longest stripes.
    bins = []
    for f in coords:
        groups = {}
        for r, c, v in points:
            groups.setdefault(f(r, c), []).append(v)
        bins.append((max(map(len, groups.values())), groups, f))

    _, groups, coord = max(bins, key=lambda x: x[0])
    stripe_colors = {}
    for q, vals in groups.items():
        # The input stripes are uniform; use the most frequent color if needed.
        stripe_colors[q] = max(set(vals), key=vals.count)

    period = 1
    for p in range(1, max(h, w) + 1):
        mapping = {}
        valid = True
        for q, v in stripe_colors.items():
            k = q % p
            if k in mapping and mapping[k] != v:
                valid = False
                break
            mapping[k] = v
        if valid:
            period = p
            break

    mapping = {}
    for q, v in stripe_colors.items():
        mapping[q % period] = v

    # In any unobserved residues, continue the cyclic color sequence.
    known = sorted(mapping)
    for k in range(period):
        if k not in mapping:
            nearest = min(known, key=lambda x: min((k - x) % period, (x - k) % period))
            mapping[k] = mapping[nearest]

    return [[mapping[coord(r, c) % period] for c in range(w)] for r in range(h)]
